from __future__ import annotations

import json
import os
from dataclasses import dataclass


def _as_bool(value: str | None, default: bool = False) -> bool:
    if value is None:
        return default
    return value.lower() in {"1", "true", "yes", "on"}


@dataclass(frozen=True, slots=True)
class Settings:
    alpaca_key: str | None
    alpaca_secret: str | None
    state_backend: str
    competition_id: str
    aws_region: str
    dynamodb_table: str
    dynamodb_endpoint_url: str | None
    auto_reconcile: bool
    public_delay_seconds: int
    runtime_role: str = "local"
    worker_poll_seconds: int = 60
    cors_origins: tuple[str, ...] = ("http://localhost:3000", "http://127.0.0.1:3000")
    challenger_manifest_uri: str | None = None
    challenger_manifest_sha256: str | None = None

    def __post_init__(self) -> None:
        if self.state_backend not in {"memory", "dynamodb"}:
            raise ValueError("STATE_BACKEND must be memory or dynamodb")
        if self.public_delay_seconds < 0:
            raise ValueError("PUBLIC_DELAY_SECONDS must be nonnegative")
        if self.runtime_role not in {"local", "reporting", "worker"}:
            raise ValueError("RUNTIME_ROLE must be local, reporting, or worker")
        if self.worker_poll_seconds < 1:
            raise ValueError("WORKER_POLL_SECONDS must be positive")

    @classmethod
    def from_env(cls) -> Settings:
        alpaca_key = os.getenv("ALPACA_KEY")
        alpaca_secret = os.getenv("ALPACA_SECRET")
        packed_credentials = os.getenv("ALPACA_CREDENTIALS")
        if packed_credentials and (not alpaca_key or not alpaca_secret):
            credentials = json.loads(packed_credentials)
            if not isinstance(credentials, dict):
                raise ValueError("ALPACA_CREDENTIALS must be a JSON object")
            alpaca_key = alpaca_key or credentials.get("ALPACA_KEY")
            alpaca_secret = alpaca_secret or credentials.get("ALPACA_SECRET")
            if not isinstance(alpaca_key, str) or not isinstance(alpaca_secret, str):
                raise ValueError("ALPACA_CREDENTIALS must contain string key and secret values")
        return cls(
            alpaca_key=alpaca_key,
            alpaca_secret=alpaca_secret,
            state_backend=os.getenv("STATE_BACKEND", "memory"),
            competition_id=os.getenv("COMPETITION_ID", "local-development"),
            aws_region=os.getenv("AWS_REGION", "us-east-1"),
            dynamodb_table=os.getenv("DYNAMODB_TABLE", "catalyst-router-local"),
            dynamodb_endpoint_url=os.getenv("DYNAMODB_ENDPOINT_URL"),
            auto_reconcile=_as_bool(os.getenv("AUTO_RECONCILE")),
            public_delay_seconds=int(os.getenv("PUBLIC_DELAY_SECONDS", "900")),
            runtime_role=os.getenv("RUNTIME_ROLE", "local"),
            worker_poll_seconds=int(os.getenv("WORKER_POLL_SECONDS", "60")),
            cors_origins=tuple(
                origin.strip()
                for origin in os.getenv(
                    "CORS_ORIGINS", "http://localhost:3000,http://127.0.0.1:3000"
                ).split(",")
                if origin.strip()
            ),
            challenger_manifest_uri=os.getenv("CHALLENGER_MANIFEST_URI"),
            challenger_manifest_sha256=os.getenv("CHALLENGER_MANIFEST_SHA256"),
        )

    def require_alpaca(self) -> tuple[str, str]:
        if not self.alpaca_key or not self.alpaca_secret:
            raise RuntimeError("ALPACA_KEY and ALPACA_SECRET are required")
        return self.alpaca_key, self.alpaca_secret

from __future__ import annotations

from dataclasses import dataclass

from catalyst_router.adapters.alpaca import AlpacaPaperBroker
from catalyst_router.adapters.dynamodb import DynamoOperationalStore
from catalyst_router.adapters.market_data import AlpacaIEXMarketData
from catalyst_router.adapters.memory import InMemoryOperationalStore
from catalyst_router.challenger import ShadowChallenger
from catalyst_router.ports import OperationalStore, PaperBroker
from catalyst_router.service import ReconciliationService
from catalyst_router.settings import Settings
from catalyst_router.worker import TradingWorker


@dataclass(slots=True)
class Container:
    settings: Settings
    store: OperationalStore
    broker: PaperBroker | None
    challenger: ShadowChallenger | None = None
    market_data: AlpacaIEXMarketData | None = None

    @classmethod
    def build(cls, settings: Settings) -> Container:
        if settings.state_backend == "memory":
            store: OperationalStore = InMemoryOperationalStore(settings.public_delay_seconds)
        elif settings.state_backend == "dynamodb":
            store = DynamoOperationalStore(
                table_name=settings.dynamodb_table,
                competition_id=settings.competition_id,
                region=settings.aws_region,
                endpoint_url=settings.dynamodb_endpoint_url,
                public_delay_seconds=settings.public_delay_seconds,
                initialize_missing=settings.runtime_role != "reporting",
            )
        else:
            raise ValueError(f"unsupported STATE_BACKEND: {settings.state_backend}")
        if settings.runtime_role != "reporting":
            store.initialize()

        broker: PaperBroker | None = None
        market_data = None
        if settings.runtime_role != "reporting" and settings.alpaca_key and settings.alpaca_secret:
            broker = AlpacaPaperBroker(settings.alpaca_key, settings.alpaca_secret)
            market_data = AlpacaIEXMarketData(settings.alpaca_key, settings.alpaca_secret)
        if settings.auto_reconcile and broker is None:
            raise RuntimeError("AUTO_RECONCILE requires Alpaca credentials")
        challenger = None
        if settings.challenger_manifest_uri:
            if not settings.challenger_manifest_sha256:
                raise RuntimeError(
                    "CHALLENGER_MANIFEST_SHA256 is required with CHALLENGER_MANIFEST_URI"
                )
            challenger = ShadowChallenger.load_from_s3(
                settings.challenger_manifest_uri,
                settings.aws_region,
                settings.challenger_manifest_sha256,
            )
        return cls(
            settings=settings,
            store=store,
            broker=broker,
            challenger=challenger,
            market_data=market_data,
        )

    def reconciliation_service(self) -> ReconciliationService:
        if self.broker is None:
            raise RuntimeError("Alpaca credentials are not configured")
        return ReconciliationService(broker=self.broker, store=self.store)

    def trading_worker(self) -> TradingWorker:
        if self.market_data is None:
            raise RuntimeError("Alpaca market data credentials are not configured")
        if self.challenger is None:
            raise RuntimeError("a challenger model is not configured")
        return TradingWorker(
            store=self.store,
            market_data=self.market_data,
            challenger=self.challenger,
        )

from __future__ import annotations

from datetime import UTC, datetime, timedelta
from typing import TYPE_CHECKING, Any
from uuid import uuid4

import boto3
from boto3.dynamodb.conditions import Key
from boto3.dynamodb.types import TypeSerializer
from botocore.exceptions import ClientError

from catalyst_router.domain import AgentState, DecisionRecord, PublicDecisionRecord

if TYPE_CHECKING:
    from mypy_boto3_dynamodb.type_defs import TransactWriteItemTypeDef


class DynamoOperationalStore:
    """Minimal DynamoDB store using optimistic writes and immutable decisions."""

    def __init__(
        self,
        *,
        table_name: str,
        competition_id: str,
        region: str,
        endpoint_url: str | None = None,
        public_delay_seconds: int = 0,
        initialize_missing: bool = True,
    ) -> None:
        resource = boto3.resource("dynamodb", region_name=region, endpoint_url=endpoint_url)
        self._table = resource.Table(table_name)
        self._client = boto3.client("dynamodb", region_name=region, endpoint_url=endpoint_url)
        self._competition_id = competition_id
        self._public_delay = timedelta(seconds=public_delay_seconds)
        self._initialize_missing = initialize_missing

    @property
    def _control_key(self) -> dict[str, str]:
        return {"PK": f"COMP#{self._competition_id}", "SK": "CONTROL#AGENT_MODE"}

    def initialize(self) -> AgentState:
        state = AgentState()
        item: dict[str, Any] = {
            **self._control_key,
            "payload": state.model_dump_json(),
            "version": state.version,
        }
        try:
            self._table.put_item(
                Item=item,
                ConditionExpression="attribute_not_exists(PK) AND attribute_not_exists(SK)",
            )
            return state
        except ClientError as exc:
            if exc.response["Error"]["Code"] != "ConditionalCheckFailedException":
                raise
            return self.get_agent_state()

    def get_agent_state(self) -> AgentState:
        response = self._table.get_item(Key=self._control_key, ConsistentRead=True)
        item = response.get("Item")
        if item is None:
            if self._initialize_missing:
                return self.initialize()
            return AgentState(reason="operational state is not initialized")
        payload = item.get("payload")
        if not isinstance(payload, (str, bytes, bytearray)):
            raise RuntimeError("agent state payload is missing or invalid")
        return AgentState.model_validate_json(payload)

    def begin_execution(self) -> AgentState:
        state = self.get_agent_state()
        new_state = state.model_copy(
            update={
                "version": state.version + 1,
                "execution_epoch": str(uuid4()),
                "reconciled_epoch": None,
                "updated_at": datetime.now(UTC),
            }
        )
        self._replace_state(state, new_state)
        return new_state

    def commit_reconciliation(self, epoch: str, record: DecisionRecord) -> AgentState:
        state = self.get_agent_state()
        if state.execution_epoch != epoch:
            raise RuntimeError("execution epoch changed during reconciliation")
        new_state = state.model_copy(
            update={
                "version": state.version + 1,
                "reconciled_epoch": epoch,
                "updated_at": datetime.now(UTC),
            }
        )
        serializer = TypeSerializer()

        def serialized(item: dict[str, Any]) -> dict[str, Any]:
            return {key: serializer.serialize(value) for key, value in item.items()}

        operations: list[TransactWriteItemTypeDef] = [
            {
                "Put": {
                    "TableName": self._table.name,
                    "Item": serialized(
                        {
                            **self._control_key,
                            "payload": new_state.model_dump_json(),
                            "version": new_state.version,
                        }
                    ),
                    "ConditionExpression": "attribute_exists(PK) AND #version = :expected",
                    "ExpressionAttributeNames": {"#version": "version"},
                    "ExpressionAttributeValues": {":expected": serializer.serialize(state.version)},
                }
            },
            *self._decision_operations(record, serializer),
        ]
        self._client.transact_write_items(TransactItems=operations)
        return new_state

    def _replace_state(self, old: AgentState, new: AgentState) -> None:
        self._table.put_item(
            Item={**self._control_key, "payload": new.model_dump_json(), "version": new.version},
            ConditionExpression="attribute_exists(PK) AND #version = :expected",
            ExpressionAttributeNames={"#version": "version"},
            ExpressionAttributeValues={":expected": old.version},
        )

    def append_decision(self, record: DecisionRecord) -> None:
        serializer = TypeSerializer()
        operations = self._decision_operations(record, serializer)
        self._client.transact_write_items(TransactItems=operations)

    def append_decision_once(self, record: DecisionRecord) -> bool:
        serializer = TypeSerializer()
        operations = self._decision_operations(record, serializer)
        try:
            self._client.transact_write_items(TransactItems=operations)
            return True
        except ClientError as exc:
            reasons = exc.response.get("CancellationReasons", [])
            reason_codes = {reason.get("Code") for reason in reasons}
            if (
                exc.response["Error"]["Code"] == "TransactionCanceledException"
                and "ConditionalCheckFailed" in reason_codes
                and reason_codes <= {"ConditionalCheckFailed", "None"}
            ):
                return False
            raise

    def _decision_operations(
        self, record: DecisionRecord, serializer: TypeSerializer
    ) -> list[TransactWriteItemTypeDef]:
        occurred = record.occurred_at.astimezone(UTC)
        visible = (occurred + self._public_delay).isoformat(timespec="microseconds")

        def serialized(item: dict[str, Any]) -> dict[str, Any]:
            return {key: serializer.serialize(value) for key, value in item.items()}

        operations: list[TransactWriteItemTypeDef] = [
            {
                "Put": {
                    "TableName": self._table.name,
                    "Item": serialized(
                        {
                            "PK": f"DECISION#{self._competition_id}#{record.decision_id}",
                            "SK": "RECORD",
                            "payload": record.model_dump_json(),
                        }
                    ),
                    "ConditionExpression": "attribute_not_exists(PK)",
                }
            }
        ]
        if record.public:
            operations.append(
                {
                    "Put": {
                        "TableName": self._table.name,
                        "Item": serialized(
                            {
                                "PK": f"PUBLIC#COMP#{self._competition_id}",
                                "SK": f"VISIBLE#{visible}#{record.decision_id}",
                                "payload": record.public_projection_json(),
                            }
                        ),
                        "ConditionExpression": "attribute_not_exists(PK)",
                    }
                }
            )
        return operations

    def list_public_decisions(self, limit: int = 50) -> list[PublicDecisionRecord]:
        now = datetime.now(UTC).isoformat(timespec="microseconds")
        response = self._table.query(
            KeyConditionExpression=Key("PK").eq(f"PUBLIC#COMP#{self._competition_id}")
            & Key("SK").between("VISIBLE#", f"VISIBLE#{now}#~"),
            ScanIndexForward=False,
            Limit=limit,
            ConsistentRead=True,
        )
        records: list[PublicDecisionRecord] = []
        for item in response["Items"]:
            payload = item.get("payload")
            if not isinstance(payload, (str, bytes, bytearray)):
                raise RuntimeError("decision payload is missing or invalid")
            records.append(PublicDecisionRecord.model_validate_json(payload))
        return records

